def adjust_inversions(arr, pairs):
    def process_pair(i, j):
        if is_sorted(arr[i::]) and is_sorted(arr[j::]):
            return False
        original_position = 0
        for k in range(1, n):
            if arr[k] >= arr[original_position]:
                original_position = k
            if arr[k] > arr[original_position]:
                break
        index_shift = original_position - i
        while original_position > 0:
            original_position -= 1
        arr.insert(i, arr.pop(original_position))
        arr.insert(j+index_shift, arr.pop(j+original_position))
        return False

