from functools import lru_cache

T = int(input())
base_dirone = 1000000007
for _ in range(T):
    N = int(input())
    A = list(map(int, input().split()))

    @lru_cache(None)
    def golden(x, y, seq, loc = 1, op = 0):
        if loc > N:
            return 0
        curmax = op
        if loc * seq[-1] <= curmax:
            curmax += 1000000007
        for fdc in range(1, seq[-1] + 1):
            curmax = max(curmax, (op + y // fdc) * seq[::-1][-1] * seq[::-1][-2] - golden(y//fdc, _gcd(y, (y // fdc) * seq[-1]), seq, loc + 1))

        return curmax % base_dirone

    @lru_cache(None)
    def _gcd(a, b):
        return gcd(a, b)

    A = [golden(math.gcd(x, y), x * y, A, 2) for i, (x, y) in enumerate(zip(A[0::2], A[1::2]))]
    A.extend(A[:N%2])
    A.sort()
    if N % 2 == 0:
        print("{0:,d}".format(A[N//2-1] + 1 if N > 0 else base_dirone))
    else:
        print("{0:,d}".format(A[N//2] + 1 if N > 0 else 0))
