def sort_indexes(n, a):
    swaps_needed = [False] * n
    last_index = [None] * n

    for i in range(n-1, -1, -1):
        if last_index[i] is not None:
            continue
        stack = []

        for j in range(i-1, -1, -1):
            if a[j] <= a[i]:
                continue

            if len(stack) == 0 or a[stack[-1]] < a[i]:
                stack.append(i)
            elif len(stack) == 1 or a[last_index[i]] < a[stack[-2]]:
                stack.append(i)
                continue

            while len(stack) > 1:
                low = stack.pop()
                high = stack.pop() if len(stack) == 0 else stack[-1]
                if a[low] <= a[high]:
                    break
                else:
                    if last_index[low] is None:
                        if swaps_needed[low]:
                            last_index[i] = high
                            last_index[high] = low
                            swaps_needed[low] = True
                    else:
                        if swaps_needed[low]:
                            last_index[i] = high
                            last_index[high] = last_index[low]
                        last_index[low] = next_to_high(last_index[i])
                        swaps_needed[last_index[i]] = True
                        last_index[high] = last_index[low]
            elif a[last_index[low]] >= a[i]:
                if swaps_needed[low]:
                    last_index[i] = high
                    last_index[high] = low
                    last_index[low] = high + 1
                    swaps_needed[low] = False
                else:
                    last_index[low] = high + 1
                    low_high_sum = (low, high)
                    stack.extend(low_high_sum[::-1])

    result = []
    freq_table = {}

    for low, high in last_index:
        p = 1 << (high - low)
        if p in freq_table:
            result.append(freq_table[p])
            freq_table[p] += 1
            freq_table[low] = 0
        else:
            freq_table[low] = low
            freq_table[p] = low
    return len(result), result

