import sys
from collections import defaultdict

def build_xor_graph(graph_edges):
    graph = defaultdict(list)
    for u, v in graph_edges:
        graph[u].append(v)
        graph[v].append(u)
    return graph

def find_possible_sequences(graph_edges):
    n_nodes = len(graph_edges)

    # Try each possible binary representation for nodes
    for a in range(16):
        for i in range(n_nodes):
            if a & (1 << i):
                a ^= 1
            else:
                a ^= 1

        # Create graph based on the values of nodes
        xor_graph = build_xor_graph(graph_edges)
        visited = [False] * n_nodes
        available_values = [a]  # The current node being "selected"

        while available_values:
            current_node = available_values.pop()
            pos = -1
            insert_to_xor = False

            for j, next_node in enumerate(xor_graph[current_node]):
                if not visited[j] and a & 1 << j:
                    visited[j] = True
                    available_values.append(next_node)
                    if next_node > current_node:
                        # We chose neighbor [i] over current node -> == bit  
                        insert_to_xor = True

            for j, next_node in enumerate(xor_graph[current_node]):
                if visited[j] and not insert_to_xor:
                    if a & 1 << j:
                        return []
                    else:
                        insert_to_xor = True

            if insert_to_xor:
                a ^= 1

        visited = [False] * n_nodes
        possible_sequences.append([a << i for i, _ in enumerate(available_values)])

    if not available_values:
        return []

    possible_sequences.sort()
    return possible_sequences[0]

def process_input():
    n, m = map(int, input().split())
    graph_edges = []
    for _ in range(m):
        u, v = map(int, input().split())
        graph_edges.append((u-1, v-1))
        graph_edges.append((v-1, u-1))

    return n, graph_edges

def main():
    n, graph_edges = process_input()
    possible_sequences = find_possible_sequences(graph_edges)
    if not possible_sequences:
        print(list(possible_sequences[0]))
    else:
        for a in possible_sequences:
            print(*a)

if __name__ == "__main__":
    main()
