from collections import defaultdict

def find_permutation(graph):
    n = len(graph)
    parent = [i for i in range(n) + [n]]  # Convert back to 0-based indices
    size = [1] * n
    parent[n] = -1

    def find(x):
        if x < 0:
            return x
        return parent[x] = find(parent[x])

    def union(x, y):
        xr, xup = find(x), n + find(y)
        if size[parent[x]] > size[parent[y]]:
            parent[parent[y]] = x
            size[parent[x]] += 1
        else:
            parent[parent[x]] = y
            size[parent[y]] += 1

    result = [0] * n
    for i in range(n):
        for j in range(i + 1, n):
            if graph[i] == graph[j]:
                union(i, j)

    for i in range(n):
        parent[i] = find(i)
        while parent[i] != parent[parent[i]]:
            result[-parent[i]] ^= i

    return result[:-1]

