from collections import defaultdict

def bisect_left(arr, tar, start=0, end=None):
    if end is None:
        end = len(arr)
    while start < end:
        mid = (start + end) // 2
        if arr[mid] == tar:
            return mid
        elif arr[mid] < tar:
            start = mid + 1
        else:
            end = mid
    return start

