from collections import defaultdict

def construct_sequence(edges):
    n = len(edges)
    graph = defaultdict(list)

    # Create an adjacency list for the graph
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    sequence = [0] * n

    def get_sequence(state, max_value):
        if state == 4:
            return [(max_value ^ state), max_value, 1 << state]
        binary_states = [2 ** i for i in range(4)]
        left_bits = [sequence[v] for v in graph[u]]
        return [[i ^ state, x, left_bits.count(i)] for i in binary_states]

    from functools import lru_cache

    @lru_cache(None)
    def explore(node, state):
        if state == 4:
            return [0, 1, 0, 1]
        changed, value, new_edges = 0, [2 ** 4] * 4, [0]
        left_bits = [sequence[v] for v in graph[u]]
        for i in range(4):
            smaller_state = state & i
            if (state & 1 << i):
                if new_edges[smaller_state - 1] + left_bits[i] > 4:
                    new_edges[smaller_state - 1] += left_bits[i]
                if new_edges[smaller_state] != value:
                    changed += 1
        if changed or (value and new_edges):
            for idx, next_val in enumerate(left_bits):
                seen = [s + (new_edges[idx] & 1) for s in get_sequence(state & ~i, next_val)]
                for se in seen:
                    if se == 0 or se == 2 or se in new_edges or se == sequence.index(seen[0]) + 1:
                        continue
                    next_sequence = copy.deepcopy(sequence)
                    next_sequence[u] = value | (state & i)
                    next_sequence[v] = (value & i) | ~i
                    new_edges.append(v)
                    if next_sequence in edges:
                        yield (next_sequence, 0)
                        if next_sequence[0] == 1:
                            yield explore(v, next_sequence[2])
                        if next_sequence[2] == 1:
                            yield explore(u, (next_sequence[0] & ~next_sequence[1]))
                    else:
                        yield from explore(v, next_sequence[2])
        return True

    for node, state in sorted([(v, sequence[i]) for i, v in enumerate(edges) if v < u]): 
        next_sequence = explore(node, state)
        while next_sequence:
            sequence = next(next_sequence)
            if 0 <= cycle := sequence > n // 2 and sequence == sequence[n // 2 + 1] * 2 + 1:
                cycle = 2
            elif cycle:
                break

        if cycle:
            break

    return sequence

