import sys
from collections import defaultdict

def find_min_swaps(N, X, Y, A):
    max_card = max(A)
    max_index = A.index(max_card)
    balance = -max(A[0:max_index+1].count(max_card))
    min_balance = sys.maxsize
    swaps = 0

    for i in range(N-1):
        new_balance = balance + max(A[i+1:], -balance) + max_card
        min_balance = min(min_balance, new_balance)
        if (min_balance >= X and min_balance <= Y):
            return swaps + (min_balance - X)
        balance = new_balance
        swaps += 1

    if (min_balance >= X and min_balance <= Y):
        return swaps + (min_balance - X)
    else:
        return -1

