from collections import deque

def calculate_max_visits(n, k, parent):
    leaves = {1}  # Start with the root leaf
    for _, pre in enumerate(parent, start=2):
        leaves.extend([c for c in parent if c == pre or c != pre and pre in leaves])
    max_visits = 0
    for v in leaves:
        q = deque([v])
        current_depth = 0
        visited = set()
        while q:
            current_depth += 1
            for _ in range(len(q)):
                node = q.popleft()
                if current_depth - k >= 0:
                    visited.add(node)
                if node not in leaves:
                    continue
                for parent in parent:
                    if parent != pre and parent in leaves:
                        q.append(parent)
    return len(visited)

