def solve_game(n, field):
    pips = []
    for i, cell in enumerate(field):
        if cell == 'P':
            pips.append((i, True))  # (index, True if already tried)
        elif cell == '*':
            pips.append((i, False))  # (index, False if already tried)

    max_pips_eaten = 0
    min_time = float('inf')
    directions = ['L', 'R']

    for i in range(n):
        pips[i][1] = i % 2 == 1  # Assign direction based on index parity

        total_pipes = len(n - [j for j in range(n) if ((j != i and pips[j][0] == i) or (j != i and pips[j][0] == i + n))])
        best_time = float('inf')
        for dir1 in directions:
            for dir2 in directions:
                time = total_pipes
                p1, p2 = 'PL', 'PR'
                use = 'p3'
                for j in range(n):
                    if use == 'p1':
                        if p1 in ('L', pips[j][1]):
                            p2 = 'P'
                    elif use == 'p2':
                        if p2 in ('L', pips[j][1]):
                            p1 = 'P'
                    use = p2
                    best_time = min(best_time, time)
                    if any(
                        (p1 + dir1 in ('PLLPL', 'LPRPL'),  # banana
                         (p2 + dir2 in ('PRLPR', 'PRRPL'), p1 < p2))  # lime
                    ): time += 1
                    if time == n: break
                else:
                    max_pips_eaten = max(max_pips_eaten, total_pipes + time)
                    break

