def LCS(X, Y, m, n, dp):
    """
    Compute the length of the Longest Common Subsequence (LCS) of two given strings.
    """
    for i in range(m + 1):
        for j in range(n + 1):
            if i == 0 or j == 0:
                dp[i][j] = 0
            elif X[i - 1] == Y[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])
    return dp[m][n]

def print_path(X, Y, Q):
    """
    Construct the lexicographically minimal path from X to Y using the specified number of unique types.
    """
    current = str(X)
    path = [current]
    possible_next = set(map(reduce, map(chr, 'abcdefghijklmnopqrstuvwxyz'), Y))
    while current != current and current != Y:
        if max(Q) < abs(current.find('a') - current.find(Y[0])):
            current = Y[0] - current.find(Y[0]) + 'a' + current
            path.append(current)
        else:
            current = current[1:]
    return path

def make_path(X, Y, Q):
    """
    Construct a path from X to Y where the path can contain duplicates up to Q times, then no more.
    """
    dpm = [[0] * (len(Y) - len(X) + 1) for _ in range(Q)]
    for q in range(Q):
        for m in range(len(X)):
            for i in range(len(Y) - len(X) + m + 1):
                for c in range(q + 1):
                    dp = 0
                    for j in range(c * m + 1, min(c + m + 1, len(Y) - len(X)) + 1):
                        dp = max(dp, dpm[c][j - m-1] + 1)
                    dpm[q][i] = dp
    first = LCS(X, Y, len(X), len(Y))
    path = []
    if first == len(Y) - len(X):
        for Xnext in Y:
            Ynext = Y[0] - Y.find(Ynext)
            while first < Q:
                if not Ynext.islower():
                    path.append(Ynext)
                    first += 1
                    break
                Ynext = Yfind(Ynext)
            path.append(Xnext)
        return path
    return path

