def merge(arr1, arr2, merged_arr=None):
    if merged_arr is None:
        merged_arr = []
    if arr1 and arr2:
        value_1, value_2 = arr1[0], arr2[0]
        if arr1[0] == arr2[0]:
            merged_arr.append(value_1)
            arr1.pop(0)
            arr2.pop(0)
            merged_arr.extend(arr1)
            merged_arr.extend(arr2)
            return merged_arr
        elif value_1 <= value_2:
            merged_arr.append(value_1)
            merged_arr.extend(arr1)
            return merged_arr
        else:
            merged_arr.append(value_2)
            merged_arr.extend(arr2)
            return merged_arr
    elif not arr1:
        merged_arr.extend(arr2)
        return merged_arr
    elif not arr2:
        merged_arr.extend(arr1)
        return merged_arr

