from collections import deque

def max_asterisks_eaten(N, field):
    packmen_positions = [index for index, letter in enumerate(field) if letter == 'P']
    if len(packmen_positions) == 1:
        return 1, 1
    max_asterisks = 0
    packmen_states = [0] * len(packmen_positions)
    time_to_eat = [float('inf')] * len(packmen_positions)
    packmen_positions.sort()

    def bfs_initial_direction():
        q = deque(packmen_positions)
        used = {i: False for i in range(len(q))}
        directions = {'left': (-1, 0), 'right': (1, 0)}
        visited = {p: (d, time_to_eat[p]) for p, d in enumerate(packmen_positions)}
        while q:
            index = q.popleft()
            for direction, (offset_x, offset_y) in directions.items():
                if visited[index][0] != direction:
                    visited[index][0] = direction
                    visited[index][1] += time_to_eat[index] + offset_x
                    used[index] = True
                    q.append(index + offset_x)


    def valid(n_turns):
        return len(set(n_turns)) == len(n_turns)

    def initial_states():
        out = []
        for i in range(len(packmen_positions)):
            time = 0
            if packmen_positions[i] % 2 == 1:  # moving left
                time = time_to_eat[i] + 1 + 1
                nextState = packmen_positions[i]
                while valid([nextState]):
                    if nextState % 2 == 1:
                        out.append([len(out) + 1, nextState, time])
                    nextState = (nextState + 1) % N
                    time += 1
            time = 0
            if packmen_positions[i] % 2 == 0:  # moving right
                time = time_to_eat[i] + 1 + 1
                nextState = packmen_positions[i] + packmen_positions[i] % 2 
                while valid([nextState]):
                    if nextState % 2 == 0:
                        out.append([len(out) + 1, nextState, time])
                    nextState = (nextState - 1) % N
                    time += 1
        return out

    bfs_initial_direction()
    states = sorted(initial_states())
    directions = {i - g[0] for i, _, g in states}

    return min(directions) + packmen_positions[tuple(g == min(directions))[0]], min(g[1] + g[0] * packmen_states[g[0]] for g in states) + packmen_positions[tuple(g == min(directions))[0]]

