from collections import defaultdict
from heapq import heappop, heappush

def find_max_visits(n, k, par):
    tree = [[] for _ in range(n)]
    for i in range(1, n):
        tree[par[i]].append(i)

    leaves = defaultdict(int)
    dp_tree = [{} for _ in range(n)]

    def dfs(v, parent):
        subtree_weight = 1
        dp_tree[v][par[v]] = (parent, subtree_weight, 0)
        for child in tree[v]:
            if child != parent:
                heapq.heappush(dp_tree[v], (dp_tree[child][par[child]][1] + 1))
        for child in tree[v]:
            if child != parent:
                dfs(child, v)

        max_visits = 1

        try:
            last_visit = parent
        except IndexError:
            last_visit = tree[v][0]
        while tree[last_visit]:
            subtree_weight += 1
            if dp_tree[last_visit][par[last_visit]][1] - dp_tree[last_visit, par[last_visit]][2] > k or subtree_weight > 2:
                break
            dp_tree[last_visit][par[last_visit]] = (par[last_visit], subtree_weight, dp_tree[last_visit][par[last_visit]][1])
            last_visit = tree[last_visit][0]
            max_visits += 1
        return max_visits

    return dfs(0, -1)

