def max_visits(n, k, parents):
    # Store parent information of each node
    parent_info = {i: parents[i-1] for i in range(1, n+1)}

    # Calculate the maximum value of i-1-j-1 that needs to be considered
    tree_queue = [(0, 'tail', None)]
    tree_depths = {}
    while len(tree_queue) != 0:
        cur_fs = tree_queue.pop(0)
        tree_depths[cur_fs[0]] = cur_fs[1]
        neis = []
        if cur_fs[2] is not None:
            if not parent_info[cur_fs[2]] in tree_depths:
                neis.append(parent_info[cur_fs[2]])
            if not cur_fs[2] in tree_depths:
                neis.append(len(tree_depths.keys()))
        if cur_fs[2] is not None and parent_info[cur_fs[2]] in tree_depths:
            neis.append(tree_depths[parent_info[cur_fs[2]]])

        if cur_fs[1] == 'head':
            tree_queue = neis + tree_queue
        elif cur_fs[1] == 'tail':
            tree_queue = tree_queue + tree_queue[::-1]
        elif cur_fs[1] == 'valid':
            tree_queue = cur_fs[2] + tree_queue

    # Now perform BFS
    layer_info = {}
    queue = [(1, 'head')] if 1 not in layer_info else [(1, 'tail')]
    while len(queue) != 0:
        node, subtree_type = queue.pop(0)
        layer = tree_depths[node]
        if subtree_type in layer_info:
            layer_info[subtree_type].add(node)
        else:
            layer_info[subtree_type] = {node}
        if node in parents:
            queue = {(parents[node], tree_depths[node])} + [((parents[nodedir], tree_depths[nodedir]) for nodedir in parents[node])]
        else:
            queue = queue + queue[::-1]

    return max(layer_info[k])
