from collections import deque

def get_steps(biathlon_map, start, end):
    n, m, k = len(biathlon_map), len(biathlon_map[0]), len(set(biathlon_map))

    if start[0] < 0 or start[0] >= n or start[1] < 0 or start[1] >= m or end[0] < 0 or end[0] >= n or end[1] < 0 or end[1] >= m:
        return "Buffer Overflow"

    if biathlon_map[start[0]][start[1]] != "S" or biathlon_map[end[0]][end[1]] != "T" or start != (0, 0):
        return "-1"

    # Initialize distances and visited set
    distances = {(x, y): float('inf') for x in range(n) for y in range(m)}
    visited = set()
    distances[start] = 0
    visited.add(start)

    queue = deque([(start, 0)])

    while queue:
        x, y, steps, current_type = queue.popleft()
        current_type = biathlon_map[x][y]

        if x == end[0] and y == end[1]:
            return steps

        for dx, dy in [(0, 1), (1, 0), (-1, 0), (0, -1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m and (nx, ny) not in visited:
                new_distance = steps + int(biathlon_map[nx][ny] in current_type)
                if new_distance < distances[(nx, ny)]:
                    distances[(nx, ny)] = new_distance
                    queue.append(((nx, ny), new_distance, biathlon_map[nx][ny] if biathlon_map[nx][ny] != "S" else ""))

    if distances.get(end, float('inf')) != float('inf'):
        return str(distances[end])
    else:
        return "Buffer Overflow"

