from collections import defaultdict
from operator import itemgetter

MOD = 10**9 + 7

class LegoTransformer:
    def __init__(self, start, end):
        self.start = start
        self.end = end
        self.length = len(start)
        self.costs = defaultdict(int)

    def transform(self):
        # Initialize cost dictionary with None keys for all positions
        for pos in range(self.length):
            self.costs[(pos, pos)] = 0

    def compute_costs(self):
        self.transform()

        # Handle boundary cases
        for pos in range(1, self.length):
            if self.start[pos - 1] != '?' or self.end[pos] != '?':
                self.costs[(pos - 1, pos)] = 0
                self.costs[(pos, pos - 1)] = 0

        # Compute costs for the rest of the positions
        for pos in range(2, self.length):
            for prev_pos in range(len(self.start)):
                if self.start[prev_pos] in ('?', '1') and self.end[prev_pos] in ('?', '0'):
                    cost = min(
                        self.costs[(prev_pos, prev_pos + 1)] if prev_pos + 1 < self.length else 2,  # Add legos
                        self.costs[(prev_pos - 1, prev_pos)] if prev_pos > 0 else 2  # Remove legos
                    )
                    self.costs[(prev_pos, prev_pos + 1)] = cost + 1
                    self.costs[(prev_pos - 1, prev_pos)] = cost + 1

    def minimum_time(self):
        self.compute_costs()
        return sum(self.costs.values()) % MOD

