modulus = 10**9 + 7

def operations_for_state(s, end_state):
    current_s = 0
    operations = 0
    for pos, char in enumerate(s):
        if char == '1':
            if current_s == 1:
                current_s = 0
            current_s ^= 1
        current_s &= end_state[pos]
    return current_s, operations + (current_s ^ 1)

def transform_to_starting_state(s, t, n):
    end_state, result = operations_for_state(s, t)
    return multiplicative_inverse(result, modulus) * (n * (n + 1) // 2) % modulus

