def remove_twos_and_reach_target(start_state, old_state, target_state):
    positions = [i for i, char in enumerate(start_state) if char == '1']
    length = len(positions)
    current_start_state = start_state
    operations = 0
    for i in range(length):
        for j in range(i + 1, min(i + 3, length)):
            new_target_state = target_state[:j] + '0' + target_state[j + 1:]
            new_start_state = current_start_state[:positions[i]] + new_target_state + current_start_state[positions[i]+1:]
            current_start_state = current_start_state[:j] + '0' + current_start_state[j + 1:]
            for pos in range(i, positions[i]):
                if old_state[pos] == '0' and target_state[positions[i]] == '0':
                    if old_state[pos] != '1':
                        current_start_state = current_start_state[:pos] + '1' + current_start_state[pos+1:]
                        old_state[pos] = '1'
                    if old_state[pos] == '1' or new_target_state[positions[i]] == '1':
