                    if old_state[pos] == '0' or new_target_state[positions[i]] == '0':
                        break
            else:
                operations += 1
            break
        else:
            for pos in range(i + 3):
                if old_state[pos] != (target_state[pos] == '0'):
                    current_start_state = current_start_state[:pos] + '0' + current_start_state[pos+1:]
                    current_start_state = current_start_state[:length] + '1' + current_start_state[length:]
