def find_path(n, m, k, grid):
    from collections import deque
    from itertools import product

    def all_different_types():
        types = [grid[0][i] for i in range(m)]
        for j in range(1, n):
            types = [min(types[i], grid[j][i]) for i in range(m)]
        final_type = grid[-1][-1]
        types.append(final_type)
        return set(types[:k + 1]) == {final_type}

    if not all_different_types():
        return "-1\n"

    start = (0, grid[0].index('S'))
    end = (n - 1, grid[-1].index('T'))

    bfs = [(start, 0, [])]
    visited = {(start): 0, start: 0}
    sequences = deque()

    while bfs:
        pos, dist, path = bfs.popleft()
        if pos == end:
            sequences.append(path + [grid[pos[0]][pos[1]]])
            continue
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            x, y = pos[0] + dx, pos[1] + dy
            if 0 <= x < n and 0 <= y < m and (x, y) not in visited:
                new_path = path + [grid[x][y]] if len(path) < k + 2 else path
                new_dir = visited.get((x, y), float("inf"))
                new_dist = grid[x][y] == 'S' or grid[x][y] == 'T' + dist if new_dir < float('inf') else grid[x][y]
                visited[(x, y)] = new_dist
                bfs.append((x, y, new_path))
            elif grid[x][y] != 'S' or grid[x][y] != 'T':
                sequences.append(path + [grid[x][y]])

    if not sequences: return "-1\n"
    return ''.join(sorted(sequences, key=lambda x: x))

n, m, k = map(int, input().split())
grid = [input().strip() for _ in range(n)]
result_path = find_path(n, m, k, grid)
print(result_path) if result_path != '-1\n' else print('-1\n')
