def generate_swaps(n, nums, swaps):
    q = deque(range(n))
    edges = {}
    for a in nums:
        edges[a] = deque(range(1, n + 1))
    while len(edges) > 1:
        parent = len(edges) - 1
        parent_ab = edges[parent].pop()
        edges[parent - 1].append(parent_ab)
        childs_set = set(edges[parent - 1])
        child_parent = list(q.pop()) if q else [parent - 1]
        while child_parent and child_parent[0] in childs_set:
            child = child_parent.pop()
            child_add_ab = edges[child].pop()
            edges[child + 1] = deque(reversed(edges[child])); 
    for i, j in sorted(edges[len(edges) - 1], key=lambda x: x[0]):
        if i != j:
            swaps.append((i, j))
    return swaps

